#include <stdio.h>
#include <limits.h>

#define MAX_N 100000

long long min(long long a, long long b) {
    return a < b ? a : b;
}

int main() {
    int N;
    scanf("%d", &N);

    long long distances[MAX_N + 1];
    for (int i = 0; i <= N; i++) {
        scanf("%lld", &distances[i]);
    }

    // distances[i] is distance from checkpoint i-1 to checkpoint i
    // We have checkpoints 0..N, we start at checkpoint 0 with new tires

    long long A, B;
    scanf("%lld %lld", &A, &B);

    // dp[i] = minimum time to reach checkpoint i
    long long dp[MAX_N + 1];
    dp[0] = 0;

    for (int i = 1; i <= N; i++) {
        dp[i] = LLONG_MAX;
        long long segment_dist = 0;
        // Try all possible last tire change points j (0 <= j < i)
        for (int j = i - 1; j >= 0; j--) {
            segment_dist += distances[j + 1]; // distance from j to i
            long long time;
            if (segment_dist <= B) {
                time = A * segment_dist;
            } else {
                time = A * B + (segment_dist - B) * (segment_dist - B);
            }
            dp[i] = min(dp[i], dp[j] + time);
        }
    }

    printf("%lld\n", dp[N]);

    return 0;
}

