typedef long long ll;

static ll minll(ll a, ll b) { return a < b ? a : b; }

int main(void) {
    int n;
    ll r, m;

    if (scanf("%d %lld %lld", &n, &r, &m) != 3) return 0;

    ll *d = (ll *)malloc((n + 1) * sizeof(ll));
    if (!d) return 0;

    d[0] = 0;
    for (int i = 1; i <= n; i++) {
        if (scanf("%lld", &d[i]) != 1) {
            free(d);
            return 0;
        }
    }

    /*
      dp[i] = minimum total time to reach checkpoint i
      Transition from checkpoint j to i (j < i):
        Let dist = d[i] - d[j]
        If we changed tires at j (or j=0 start), then segment cost is:
          r + dist * dist   if dist <= m
          r + (2*dist - m) * m   otherwise
      We subtract r at the end because no tire change is needed at finish.
    */

    const ll INF = LLONG_MAX / 4;
    ll *dp = (ll *)malloc((n + 1) * sizeof(ll));
    if (!dp) {
        free(d);
        return 0;
    }

    dp[0] = 0;
    for (int i = 1; i <= n; i++) dp[i] = INF;

    for (int i = 1; i <= n; i++) {
        for (int j = 0; j < i; j++) {
            ll dist = d[i] - d[j];
            ll cost;
            if (dist <= m) {
                cost = r + dist * dist;
            } else {
                cost = r + (2 * dist - m) * m;
            }
            dp[i] = minll(dp[i], dp[j] + cost);
        }
    }

    printf("%lld\n", dp[n] - r);

    free(dp);
    free(d);
    return 0;
}

