            }
        }

        // DP[i] = minimum time to reach checkpoint i
        long[] dp = new long[n + 1];
        Arrays.fill(dp, Long.MAX_VALUE);
        dp[0] = 0;

        for (int i = 1; i <= n; i++) {
            // Try all possible last tire change at checkpoint j (0 <= j < i)
            for (int j = 0; j < i; j++) {
                if (dp[j] == Long.MAX_VALUE) continue;
                long time = dp[j] + segmentTime[j][i] + (j == 0 ? 0 : r);
                // No tire change at start (j=0) means no r added
                // Actually we add r for each tire change except possibly at start
                // But we consider j as the last checkpoint where we changed tires
                // So from j to i, no change, then at i we may change (handled later)
                // Or we consider that we change at i, so cost r is added for that change
                // The transition: we are at j after changing tires there, then go to i without change,
                // then at i we change tires (add r). For i = n, we don't need to change after final.
                // So we adjust: add r for tire change at i, except when i == n (no change needed at end)
                // Actually we need to decide if we change at i. Let's define dp[i] as min time to reach i
                // and have just changed tires at i (or at start for i=0).
                // Then transition: from j (where we changed) to i (where we change again)
                // cost = dp[j] + segmentTime[j][i] + r (change at i)
                // For i = n, we may not change at n, so we consider final answer as min over j of dp[j] + segmentTime[j][n]
                if (i < n) {
                    dp[i] = Math.min(dp[i], dp[j] + segmentTime[j][i] + r);
                }
            }
        }

        // For final checkpoint, we may not change tires
        long ans = Long.MAX_VALUE;
        for (int j = 0; j < n; j++) {
            if (dp[j] == Long.MAX_VALUE) continue;
            ans = Math.min(ans, dp[j] + segmentTime[j][n]);
        }

        System.out.println(ans);
    }
