public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int n;
        try {
            n = fs.nextInt();
        } catch (Exception e) {
            return;
        }

        long[] d = new long[n + 1];
        for (int i = 1; i <= n; i++) d[i] = fs.nextLong();

        long r = fs.nextLong();
        long t = fs.nextLong();

        // dp[i] = minimum total time to reach checkpoint i
        long[] dp = new long[n + 1];
        Arrays.fill(dp, Long.MAX_VALUE / 4);
        dp[0] = 0;

        // checkpoint 0 is start at distance 0
        // If last tire change was at checkpoint j, then for reaching i > j:
        // time for that segment = r + t * (d[i] - d[j])^2
        // (If the original statement has a slightly different formula involving
        // the same "distance since last tire change", this DP structure is the solution.)
        //
        // We also allow changing tires at checkpoint i, which is naturally represented
        // by ending a segment at i and starting the next from i.

        for (int i = 1; i <= n; i++) {
            for (int j = 0; j < i; j++) {
                long dist = d[i] - d[j];
                long cost = dp[j] + r + t * dist * dist;
                if (cost < dp[i]) dp[i] = cost;
            }
        }

        System.out.println(dp[n]);
    }
}

